"""UnitCircleWaves: sine or cosine generated by a radius turning round the unit circle, then
stretched and shifted to y = a sin(bx) + c (AM 10.2, 10.3, supports 4024 2.11; PRIMITIVES.md
#41, AM-EXT).

As the angle x turns from 0° to 360°, the height of the point on the unit circle is sin x (its
across distance is cos x), and the graph of that height against x is the wave. Then a sets the
amplitude, b the number of cycles in 360° (period 360°/b) and c the shift up or down. Angles
are in degrees, as in O Level. The key values are computed by SymPy.
"""

from typing import Annotated, Literal

import numpy as np
import sympy as sp
from manim import (
    Circle,
    DashedLine,
    Dot,
    Line,
    TracedPath,
    ValueTracker,
    VGroup,
    always_redraw,
)
from pydantic import Field

from app.contracts import LayoutContract, PredicateFailure, PrimitiveParams, Region
from app.primitives import style
from app.primitives.plotting import curve, label, make_plot, text_line
from app.primitives.staged import Stage, StagedPrimitive, by_level, combine, stage
from app.primitives.symbolic import exact, format_value, latex_value

CIRCLE = Region(x_min=0.0, x_max=0.2, y_min=0.0, y_max=0.8)
WAVE = Region(x_min=0.2, x_max=0.62, y_min=0.0, y_max=0.8)  # below the title band
Coefficient = Annotated[float, Field(ge=-10, le=10)]


class UnitCircleWavesParams(PrimitiveParams):
    function: Literal["sin", "cos"] = "sin"
    a: Coefficient = Field(default=1, description="Amplitude factor a; not 0")
    b: Annotated[float, Field(gt=0, le=6)] = Field(default=1, description="Cycles in 360 degrees")
    c: Coefficient = Field(default=0, description="Vertical shift")


class UnitCircleWaves(StagedPrimitive[UnitCircleWavesParams]):
    primitive_id = "UnitCircleWaves"
    version = "1"
    topic = "Trigonometry"
    params_model = UnitCircleWavesParams
    layout = LayoutContract(
        region=style.GRAPH_REGION,
        allowed_overlaps=[
            ("axes", "*"),
            ("wave*", "*"),
            ("circle*", "*"),
            ("guides", "*"),
            ("features", "*"),
        ],
    )

    def default_params(self) -> UnitCircleWavesParams:
        return UnitCircleWavesParams(function="sin", a=2, b=2, c=1)

    def validate(self, params: UnitCircleWavesParams) -> list[PredicateFailure]:
        if params.a == 0:
            return [
                PredicateFailure(
                    kind="consistency",
                    predicate="a_nonzero",
                    message="a = 0 gives a flat line, not a wave",
                    parameters=["a"],
                )
            ]
        return []

    def computed_values(self, params: UnitCircleWavesParams) -> dict[str, str]:
        a, b, c = (exact(v) for v in (params.a, params.b, params.c))
        return {
            "amplitude": format_value(abs(a)),
            "period": format_value(360 / b),
            "maximum": format_value(c + abs(a)),
            "minimum": format_value(c - abs(a)),
        }

    def build(self, params: UnitCircleWavesParams, level):
        a, b, c = (float(exact(v)) for v in (params.a, params.b, params.c))
        trig = np.sin if params.function == "sin" else np.cos
        title, _ = style.graph_boxes(style.GRAPH_REGION)
        upper, lower = style.title_lines(title)
        top = max(1.0, c + abs(a))
        bottom = min(-1.0, c - abs(a))
        plot = make_plot(
            WAVE,
            [0, 360],
            [bottom, top],
            x_label=r"x^\circ",
            title=False,
            y_ticks=4,
            x_axis=(0, 360, 90),
        )
        circle_box = style.region_box(CIRCLE).shrink(0.25)
        unit = plot.point(0, 1)[1] - plot.point(0, 0)[1]
        radius = min(unit, circle_box.width / 2)
        centre = np.array([circle_box.center[0], plot.point(0, 0)[1], 0.0])

        def base(x):
            return float(trig(np.radians(x)))

        def final(x):
            return a * float(trig(np.radians(b * x))) + c

        parts = {
            "axes": plot.axes,
            "x_label": plot.x_label,
            "y_label": plot.y_label,
            "circle": Circle(radius=radius, color=style.TEXT_COLOUR, stroke_width=2).move_to(
                centre
            ),
            "circle_axes": VGroup(
                Line(
                    centre + [-radius - 0.15, 0, 0], centre + [radius + 0.15, 0, 0], stroke_width=2
                ),
                Line(
                    centre + [0, -radius - 0.15, 0], centre + [0, radius + 0.15, 0], stroke_width=2
                ),
            ),
            "base_title": text_line(rf"y = \{params.function} x", upper),
            "wave_base": curve(plot, base, 0, 360, colour=style.CURVE_COLOUR),
            "final_title": text_line(rf"y = {_formula(params)}", upper),
            "wave_final": curve(plot, final, 0, 360, colour=style.TANGENT_COLOUR),
            "features": _features(plot, a, b, c),
            "key": text_line(
                rf"\text{{amplitude }} {latex_value(abs(exact(params.a)))},\ "
                rf"\text{{period }} {latex_value(360 / exact(params.b))}^\circ,\ "
                rf"\text{{centre line }} y = {latex_value(exact(params.c))}",
                lower,
                size=34,
            ),
        }
        self._motion = (plot, centre, radius, trig, params.function)
        return parts

    def turn(self, scene, parts, level, run_time, min_run_time):
        """A radius turns once round the circle while its height is traced as the wave."""
        plot, centre, radius, trig, function = self._motion
        angle = ValueTracker(0)

        def tip():
            t = np.radians(angle.get_value())
            return centre + radius * np.array([np.cos(t), np.sin(t), 0])

        def height():
            value = float(trig(np.radians(angle.get_value())))
            return plot.point(angle.get_value(), value)

        moving = always_redraw(
            lambda: VGroup(
                Line(centre, tip(), color=style.HIGHLIGHT_COLOUR, stroke_width=4),
                Dot(tip(), color=style.HIGHLIGHT_COLOUR),
                DashedLine(
                    tip()
                    if function == "sin"
                    else centre + [radius * np.cos(np.radians(angle.get_value())), 0, 0],
                    height(),
                    color=style.HIGHLIGHT_COLOUR,
                    stroke_width=2,
                ),
                Dot(height(), color=style.POINT_COLOUR),
            )
        )
        trace = TracedPath(height, stroke_color=style.POINT_COLOUR, stroke_width=3)
        scene.add(moving, trace)
        hold = min(0.15, 0.2 * run_time)
        animation_time = min(max(min_run_time, 0.6 * run_time), run_time - hold)
        scene.play(angle.animate.set_value(360), run_time=animation_time)
        scene.remove(moving, trace)
        scene.wait(run_time - animation_time)

    def stages(self, params: UnitCircleWavesParams, level) -> list[Stage]:
        what = "height" if params.function == "sin" else "across distance"
        plain = params.a == 1 and params.b == 1 and params.c == 0
        setup = stage(
            "setup",
            f"The unit circle, and axes for the angle x and {params.function} x",
            2.5,
            ["circle", "circle_axes", "axes", "x_label", "y_label", "base_title"],
        )
        turn_words = f"As the radius turns, its {what} traces the {params.function} wave"
        turn = stage("turn", turn_words, 6.0, motion="turn")
        # The same turn, leaving the finished wave on screen: for the shorter levels.
        turn_to_wave = stage("turn", turn_words, 6.0, ["wave_base"], motion="turn")
        wave = stage(
            "wave",
            f"The graph of y = {params.function} x from 0 to 360 degrees",
            2.0,
            ["wave_base"],
        )
        transform = stage(
            "transform",
            "a stretches it up and down, b squeezes it across, c moves it up",
            3.5,
            ["wave_final"],
            morph=[("base_title", "final_title")],
        )
        features = stage(
            "features",
            "Read the amplitude, the period and the centre line",
            3.0,
            ["features", "key"],
            emphasise=["key"],
        )
        if plain:
            return by_level(
                level, [setup, turn, wave], lambda s: s, lambda s: [setup, turn_to_wave]
            )

        def standard(s):
            return [setup, turn, combine("transform", "Stretch and shift the wave", 4.0, *s[2:])]

        def concise(s):
            return [
                setup,
                turn_to_wave,
                combine("transform", "The transformed wave", 3.5, transform, features),
            ]

        return by_level(level, [setup, turn, wave, transform, features], standard, concise)


def _formula(params: UnitCircleWavesParams) -> str:
    a, b, c = (exact(v) for v in (params.a, params.b, params.c))
    lead = "" if a == 1 else ("-" if a == -1 else latex_value(a))
    inside = "x" if b == 1 else f"{latex_value(b)}x"
    shift = "" if c == 0 else (f" + {latex_value(c)}" if c > 0 else f" - {latex_value(-c)}")
    return rf"{lead}\{params.function} {inside}{shift}"


def _features(plot, a: float, b: float, c: float) -> VGroup:
    """Dashed lines at the maximum, the minimum and the centre line."""
    group = VGroup()
    for y, colour in (
        (c + abs(a), style.RISE_COLOUR),
        (c - abs(a), style.RISE_COLOUR),
        (c, style.SECANT_COLOUR),
    ):
        group.add(DashedLine(plot.point(0, y), plot.point(360, y), color=colour, stroke_width=2))
    period_end = 360 / b
    if period_end > 360:
        return group  # one period does not fit on 0 to 360 degrees
    text = label(rf"{format_value(sp.nsimplify(period_end))}^\circ", colour=style.RISE_COLOUR)
    group.add(text.next_to(plot.point(period_end, c - abs(a)), [0, -1, 0], buff=0.1))
    return group
